-- ============================================
-- LUMA — Thème 1 (Restaurant) : 3e scénario COURT x4
-- ============================================


update scenarios set content = '{"characters": {"waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "waiter", "text": "Can I get you anything else, or would you like the check?", "text_fr": "Je peux vous apporter autre chose, ou vous voulez l''addition ?", "choices": [{"text": "Just the check, please.", "text_fr": "Juste l''addition, s''il vous plaît.", "next": "n2"}, {"text": "Actually, could we get dessert menus first?", "text_fr": "En fait, on pourrait avoir les cartes des desserts d''abord ?", "next": "n2b"}]}, "n2": {"speaker": "waiter", "text": "Of course, I''ll bring that right over.", "text_fr": "Bien sûr, je vous l''apporte tout de suite.", "choices": [{"text": "Thank you.", "text_fr": "Merci.", "next": "n3"}]}, "n2b": {"speaker": "waiter", "text": "Absolutely, here you go — take your time.", "text_fr": "Bien sûr, les voici — prenez votre temps.", "choices": [{"text": "We''ll skip dessert actually, just the check please.", "text_fr": "On va sauter le dessert en fait, juste l''addition s''il vous plaît.", "next": "n2"}, {"text": "We''ll take two of the chocolate cakes.", "text_fr": "On va prendre deux gâteaux au chocolat.", "next": "n2c"}]}, "n2c": {"speaker": "waiter", "text": "Great choice! I''ll bring those and the check together after.", "text_fr": "Excellent choix ! Je vous apporte ça et l''addition ensemble après.", "choices": [{"text": "Perfect, thank you.", "text_fr": "Parfait, merci.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Here''s the check whenever you''re ready.", "text_fr": "Voici l''addition quand vous serez prêt.", "choices": [{"text": "Can we split it in two, please?", "text_fr": "On peut la partager en deux, s''il vous plaît ?", "next": "n4"}, {"text": "I''ll take care of the whole thing.", "text_fr": "Je m''occupe de tout.", "next": "n4b"}, {"text": "Do you accept card payment?", "text_fr": "Vous acceptez le paiement par carte ?", "next": "n4c"}]}, "n4": {"speaker": "waiter", "text": "Of course, I''ll bring two separate machines.", "text_fr": "Bien sûr, je vous apporte deux terminaux séparés.", "choices": [{"text": "Thank you, that''s easier for us.", "text_fr": "Merci, c''est plus simple pour nous.", "next": "n5"}]}, "n4b": {"speaker": "waiter", "text": "Very generous of you! I''ll bring the machine over.", "text_fr": "Très généreux de votre part ! Je vous apporte le terminal.", "choices": [{"text": "It''s my pleasure, honestly.", "text_fr": "C''est un plaisir, honnêtement.", "next": "n5"}]}, "n4c": {"speaker": "waiter", "text": "Yes, we accept all major cards, and contactless too.", "text_fr": "Oui, on accepte toutes les cartes principales, et le sans contact aussi.", "choices": [{"text": "Perfect, I''ll pay by card then.", "text_fr": "Parfait, je vais payer par carte alors.", "next": "n5"}]}, "n5": {"speaker": "waiter", "text": "Here you go. Take your time with the tip, no rush.", "text_fr": "Voilà. Prenez votre temps pour le pourboire, aucune urgence.", "choices": [{"text": "What''s a normal tip here?", "text_fr": "C''est quoi un pourboire normal ici ?", "next": "n6"}, {"text": "I''ll add 15%, does that work?", "text_fr": "Je vais ajouter 15%, ça convient ?", "next": "n6b"}, {"text": "Is a tip already included?", "text_fr": "Un pourboire est déjà inclus ?", "next": "n6c"}]}, "n6": {"speaker": "waiter", "text": "Typically between 15 and 20 percent, but it''s always appreciated, not required.", "text_fr": "En général entre 15 et 20 pourcent, mais c''est toujours apprécié, pas obligatoire.", "choices": [{"text": "I''ll do 18%, the service was great.", "text_fr": "Je vais faire 18%, le service était excellent.", "next": "n7"}]}, "n6b": {"speaker": "waiter", "text": "That''s very generous, thank you!", "text_fr": "C''est très généreux, merci !", "choices": [{"text": "You earned it, honestly.", "text_fr": "Vous l''avez mérité, honnêtement.", "next": "n7"}]}, "n6c": {"speaker": "waiter", "text": "No, tipping isn''t included here — it''s always separate and optional.", "text_fr": "Non, le pourboire n''est pas inclus ici — c''est toujours séparé et optionnel.", "choices": [{"text": "Good to know, I''ll add a tip then.", "text_fr": "Bon à savoir, je vais ajouter un pourboire alors.", "next": "n6"}]}, "n7": {"speaker": "waiter", "text": "Thank you so much, that''s very kind of you!", "text_fr": "Merci beaucoup, c''est très gentil de votre part !", "choices": [{"text": "Thank you for the great service.", "text_fr": "Merci pour l''excellent service.", "next": "end_generous"}]}, "end_generous": {"speaker": "waiter", "text": "It was a pleasure serving you tonight, have a wonderful evening!", "text_fr": "Ce fut un plaisir de vous servir ce soir, passez une excellente soirée !", "end": true, "ending_label": "Addition réglée avec élégance 💳"}}}'::jsonb, is_playable = true
where title = 'Payer et laisser un pourboire'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
